const fs = require("fs");
const path = require("path");
const { CliError } = require("./errors");
const { createFile } = require("./fileUtils");
const { readStatic } = require("../templates/static");
const {
  MODULE_DEPENDENCIES,
  migrationScripts,
  sortKeys,
} = require("../templates/projectTemplates");

/**
 * Helpers for files a project needs besides the module itself.
 * Projects generated by older versions lack some of them; they are added on demand,
 * so new modules also work there.
 */

/**
 * The file that holds the route markers.
 * Since v1.3.0 that is src/app; older projects keep everything in src/index.
 */
function routesFile(projectPath, language) {
  const app = path.join(projectPath, "src", `app.${language}`);
  return fs.existsSync(app) ? app : path.join(projectPath, "src", `index.${language}`);
}

/** Whether the project's SQL helper runs migrations (projects generated before v1.3.0 use sync()) */
function supportsMigrations(projectPath, language) {
  const sqlHelper = path.join(projectPath, "src", "config", `sql.${language}`);
  return fs.existsSync(sqlHelper) && fs.readFileSync(sqlHelper, "utf-8").includes("getMigrator");
}

/** Whether generated modules should get a test file */
function supportsTests(projectPath, language, packageJson) {
  return (
    Boolean(packageJson.devDependencies?.supertest) &&
    fs.existsSync(path.join(projectPath, "src", `app.${language}`))
  );
}

/** Copy a static template into the project unless the file is already there */
function ensureStaticFile(projectPath, relativePath, templateName, language) {
  const filePath = path.join(projectPath, relativePath);
  if (fs.existsSync(filePath)) return false;

  createFile(filePath, readStatic(templateName, language));
  return true;
}

/** Files every module imports: the validation middleware and the list query helpers */
function ensureModuleSupport(projectPath, language) {
  ensureStaticFile(projectPath, `src/middleware/validate.${language}`, "validate", language);
  ensureStaticFile(projectPath, `src/utils/listQuery.${language}`, "listQuery", language);
}

/** The migrate script and its npm scripts (SQL projects) */
function ensureMigrationSupport(projectPath, language, packageJson) {
  ensureStaticFile(projectPath, `src/scripts/migrate.${language}`, "migrate", language);

  // Add the scripts that are missing, after the existing ones; never overwrite a script
  const existing = packageJson.scripts || {};
  const missing = Object.entries(migrationScripts(language)).filter(
    ([name]) => !(name in existing)
  );
  packageJson.scripts = { ...existing, ...Object.fromEntries(missing) };
}

function readPackageJson(projectPath) {
  try {
    return JSON.parse(fs.readFileSync(path.join(projectPath, "package.json"), "utf-8"));
  } catch (error) {
    throw new CliError(`Cannot read package.json: ${error.message}`);
  }
}

function writePackageJson(projectPath, packageJson) {
  fs.writeFileSync(
    path.join(projectPath, "package.json"),
    JSON.stringify(packageJson, null, 2) + "\n"
  );
}

/**
 * Add dependencies that are missing from package.json (existing versions are kept)
 * @returns {string[]} - Names of the packages that were added
 */
function addDependencies(packageJson, dependencies) {
  const missing = Object.keys(dependencies).filter(
    (name) => !packageJson.dependencies?.[name] && !packageJson.devDependencies?.[name]
  );

  if (missing.length > 0) {
    packageJson.dependencies = sortKeys({
      ...packageJson.dependencies,
      ...Object.fromEntries(missing.map((name) => [name, dependencies[name]])),
    });
  }

  return missing;
}

module.exports = {
  MODULE_DEPENDENCIES,
  routesFile,
  supportsMigrations,
  supportsTests,
  ensureModuleSupport,
  ensureMigrationSupport,
  readPackageJson,
  writePackageJson,
  addDependencies,
};
